messages.content:
Tool response:
Tool: create_transaction
Description: Manually enter a transaction with specified amount, type, description, and date. 
Optionally assign it to a category.
Parameters:
    {
      "type": "object",
      "properties": {
        "amount": {
          "type": "number",
          "exclusiveMinimum": 0.0,
          "title": "Amount",
          "description": "Transaction amount (must be positive)"
        },
        "transaction_type": {
          "type": "string",
          "pattern": "^(income|expense)$",
          "title": "Transaction Type",
          "description": "Type of transaction: 'income' or 'expense'"
        },
        "description": {
          "type": "string",
          "title": "Description",
          "description": "Description of the transaction"
        },
        "transaction_date": {
          "type": "string",
          "title": "Transaction Date",
          "description": "Date of the transaction in YYYY-MM-DD format"
        },
        "category_id": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "title": "Category Id",
          "description": "Optional ID of the category to assign to this transaction"
        }
      },
      "required": [
        "amount",
        "transaction_type",
        "description",
        "transaction_date"
      ]
    }
